package com.dexm.personajes.adapter.out.persistence;
import jakarta.persistence.*;
@Entity @Table(name="shield_catalog") public class ShieldCatalogEntity { @Id private String id; @Column(nullable=false) private String name; @Column(columnDefinition="text") private String description; @Column(name="hit_points",nullable=false) private int hitPoints; @Column(name="image_url",columnDefinition="longtext") private String imageUrl; @Column(nullable=false) private boolean official; protected ShieldCatalogEntity(){} public ShieldCatalogEntity(String i,String n,String d,int p,String u,boolean o){id=i;name=n;description=d;hitPoints=p;imageUrl=u;official=o;} public String getId(){return id;} public String getName(){return name;} public String getDescription(){return description;} public int getHitPoints(){return hitPoints;} public String getImageUrl(){return imageUrl;} public boolean isOfficial(){return official;} }
